def copiar_desde_habitos(modelos):
    """Copia los datos de las tablas viejas (app habitos) a las nuevas, con los mismos ids."""

    def copiar(apps, schema_editor):
        from django.core.management.color import no_style

        nuevos = []
        for nombre, campos in modelos:
            Viejo = apps.get_model("habitos", nombre)
            Nuevo = apps.get_model("identidades", nombre)
            Nuevo.objects.bulk_create(
                Nuevo(**{campo: getattr(fila, campo) for campo in ["id", *campos]})
                for fila in Viejo.objects.all()
            )
            nuevos.append(Nuevo)
        # Con ids copiados a mano, PostgreSQL necesita poner al día su contador de ids
        conexion = schema_editor.connection
        for sql in conexion.ops.sequence_reset_sql(no_style(), nuevos):
            schema_editor.execute(sql)

    return copiar


